// ✅ Self-validating, immutable value object.
public readonly record struct Money {
    public decimal Amount { get; }
    public Currency Currency { get; }

    public Money(decimal amount, Currency currency) {
        if (amount < 0) throw new ArgumentOutOfRangeException(nameof(amount));
        Amount = amount; Currency = currency;
    }

    public Money Add(Money other) {
        if (other.Currency != Currency)
            throw new InvalidOperationException("Currency mismatch");
        return new Money(Amount + other.Amount, Currency);
    }

    public Money ApplyPercent(decimal percent)
        => new(Amount * (1 - percent), Currency);

    public override string ToString() => $"{Amount:0.00} {Currency}";
}

// Invalid states are unrepresentable: no negative Money, no bare amount.
var fee = new Money(10m, Currency.USD).ApplyPercent(0.2m);  // 8.00 USD
